gOq(){return"\u0627\u0644\u0628\u0627\u062f\u0626\u0629"},
gOf(){return"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a"},
gOg(){return"\u064a\u062a\u062d\u0643\u0645 \u0628\u0645\u0627 \u064a\u064f\u0633\u0645\u062d \u0644\u0644\u0645\u0648\u0638\u0641\u064a\u0646\u060c \u0648\u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0639\u0646\u062f \u0625\u0631\u0633\u0627\u0644 \u062d\u0627\u0644\u0629\u060c \u0628\u0625\u0631\u0641\u0627\u0642\u0647 \u0628\u0627\u0644\u062d\u0627\u0644\u0629."},
