gDZ(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc \u0626\u06ce\u0633\u062a\u0627"},
gPd(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644\u06ce\u06a9\u06cc \u062f\u0631\u0648\u0633\u062a \u0628\u0646\u0648\u0648\u0633\u06d5."},
gOM(){return"\u0633\u06d5\u06cc\u0631\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06cc \u0646\u0648\u06ce\u062a \u0628\u06a9\u06d5 \u0628\u06c6 \u062f\u06b5\u0646\u06cc\u0627\u0628\u0648\u0648\u0646\u06d5\u0648\u06d5 \u0644\u06d5 \u06af\u06c6\u0695\u06cc\u0646\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644 \u2014 \u0644\u06d5\u0648\u0627\u0646\u06d5\u06cc\u06d5 \u06a9\u06d5\u0645\u06ce\u06a9 \u06a9\u0627\u062a \u0628\u062e\u0627\u06cc\u06d5\u0646\u06ce\u062a."},
gQb(){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u062f\u0646\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06cc \u0646\u0648\u06ce"},
gOw(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gPF(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc \u0646\u0648\u06ce"},
gOE(){return"\u062f\u06b5\u0646\u06cc\u0627\u0628\u0648\u0648\u0646\u06d5\u0648\u06d5 \u0644\u06d5 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc \u0646\u0648\u06ce"},
gE1(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc \u0646\u0648\u06ce \u062f\u06d5\u0628\u06ce\u062a \u0644\u0627\u0646\u06cc\u06a9\u06d5\u0645 \u0666 \u067e\u06cc\u062a \u0628\u06ce\u062a."},
gE2(){return"\u0648\u0634\u06d5 \u0646\u0647\u06ce\u0646\u06cc\u06cc\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u0627\u0646 \u0648\u06d5\u06a9 \u06cc\u06d5\u06a9 \u0646\u06cc\u0646."},
gPJ(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5."},
gE_(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u0645"},
gOH(){return"\u062f\u0627\u0648\u0627\u06cc \u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0628\u06a9\u06d5. \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0631\u062f\u06d5\u0686\u06cc\u062a \u0648 \u0626\u06cc\u062a\u0631 \u0646\u0627\u062a\u0648\u0627\u0646\u06cc\u062a \u0628\u0686\u06cc\u062a\u06d5 \u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u060c \u0648 \u0632\u0627\u0646\u06cc\u0627\u0631\u06cc\u06cc\u06d5 \u062a\u0627\u06cc\u0628\u06d5\u062a\u06d5\u06a9\u0627\u0646\u062a \u0644\u06d5 \u0645\u0627\u0648\u06d5\u06cc 30 \u0695\u06c6\u0698\u062f\u0627 \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u0646\u06d5\u0648\u06d5. \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u0627\u0646\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06a9\u06d5\u062a (\u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u060c \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646\u060c \u0645\u0648\u0648\u0686\u06d5\u06a9\u0627\u0646) \u0644\u06d5 \u062f\u06d5\u0641\u062a\u06d5\u0631\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06a9\u06d5\u062f\u0627 \u062f\u06d5\u0645\u06ce\u0646\u0646\u06d5\u0648\u06d5. \u0626\u06d5\u06af\u06d5\u0631 \u062a\u06c6 \u062a\u0627\u0642\u06d5 \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06a9\u06d5\u062a\u06cc\u062a\u060c \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u0645\u0627\u0646 \u067e\u06ce\u0648\u06d5 \u0628\u06a9\u06d5 \u0628\u06c6 \u062f\u0627\u062e\u0633\u062a\u0646\u06cc \u062a\u06d5\u0648\u0627\u0648\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06a9\u06d5."},
gOI(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u0645"},
gOJ(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0626\u06ce\u0633\u062a\u0627 \u0646\u0627\u0686\u0627\u0644\u0627\u06a9 \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0648 \u0644\u06d5 \u0645\u0627\u0648\u06d5\u06cc 30 \u0695\u06c6\u0698\u062f\u0627 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5. \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632\u0628\u0648\u0648\u0646\u06d5\u0648\u06d5 \u0628\u06a9\u0631\u06ce\u062a. \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u062a \u0628\u0646\u0648\u0648\u0633\u06d5 \u0628\u06c6 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5."},
gQc(){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u062f\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc \u0646\u0648\u06ce"},
gOi(){return"\u0646\u0627\u0648\u06cc \u0644\u0642"},
gOO(){return"\u0646\u0631\u062e\u06cc \u062f\u06c6\u0644\u0627\u0631"},
gON(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0628\u06c6 \u06a9\u06d5\u06cc\u0633 \u0648 \u062a\u06ce\u0686\u0648\u0648 \u0648 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06cc \u0646\u0648\u06ce"},
gO0(){return"\u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646"},
gPK(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u062a\u06d5\u0644\u06d5\u0641\u06c6\u0646"},
