ga0N(){return"\u0644\u06d5 \u0642\u06c6\u0646\u0627\u063a\u06cc \u062c\u06cc\u0627\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u060c \u062a\u06d5\u0646\u0647\u0627 \u0633\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u06d5\u0631\u06d5 \u06cc\u06d5\u06a9\u0627\u0646\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u0645\u0627\u062f\u062f\u06d5\u06cc\u06d5 \u067e\u06ce\u0634\u062f\u06d5\u062e\u0627\u062a \u0644\u06d5 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0686\u06d5\u0646\u062f \u062c\u06c6\u0631\u06cc."},
ga0P(){return"\u0628\u06ce \u0695\u06ce\u0695\u06d5\u0648 (\u0644\u06d5\u06af\u06d5\u06b5 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5 \u062f\u06d5\u062c\u0648\u06b5\u06ce\u062a)"},
ga_U(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce \u0628\u06d5 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u062e\u06c6\u06a9\u0627\u0631 \u0695\u06ce\u0695\u06d5\u0648\u06cc \u0628\u06d5\u0631\u0647\u06d5\u0645\u0647\u06ce\u0646\u0627\u0646\u06cc \u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f\u06cc \u0666 \u0642\u06c6\u0646\u0627\u063a\u06cc \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u06ce\u062a (\u0644\u06d5\u06af\u06d5\u06b5 \u0644\u06cc\u0633\u062a\u06d5\u06cc \u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f\u06cc \u0661\u0666 \u0695\u06d5\u0646\u06af \u0626\u06d5\u06af\u06d5\u0631 \u0695\u06d5\u0646\u06af\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0628\u06ce\u062a) \u2014 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u06cc\u0627\u0646 \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u06af\u06c6\u0695\u062f\u0631\u06ce\u0646."},
