ga17(){return"\u0626\u0627\u0633\u062a\u06d5\u06a9\u0627\u0646\u06cc \u0646\u0631\u062e"},
ga16(){return'\u062a\u0627\u06af\u06cc \u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5 \u0648\u06d5\u06a9 "\u0626\u0627\u0633\u0627\u06cc\u06cc"/"\u067e\u0631\u06ce\u0645\u06cc\u06c6\u0645" \u06a9\u06d5 \u0645\u0627\u062f\u062f\u06d5\u06cc\u06d5\u06a9 \u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0647\u06d5\u06b5\u0628\u06af\u0631\u06ce\u062a \u2014 \u062f\u0648\u0648 \u06cc\u0627\u0646 \u0632\u06cc\u0627\u062a\u0631 \u0645\u0627\u062f\u062f\u06d5 \u0628\u06c6 \u0647\u06d5\u0645\u0627\u0646 \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633 \u0628\u06d5 \u062c\u06cc\u0627\u0648\u0627\u0632\u06cc \u062a\u0627\u06af \u0628\u06a9\u06d5 \u0628\u06c6 \u067e\u06ce\u0634\u06a9\u06d5\u0634\u06a9\u0631\u062f\u0646\u06cc \u0644\u06cc\u0633\u062a\u06cc \u0646\u0631\u062e\u06cc \u062f\u0648\u0648\u06d5\u0645 \u0628\u06d5\u0628\u06ce \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062e\u0648\u062f\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06d5.'},
gHu(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0626\u0627\u0633\u062a"},
